// Node tests for the Markdown slugs, renderer and search (run: node web/static/search_engine.test.mjs).
// The manuals' own tables of contents link to '#<anchor>' targets generated by GitHub; every such link must
// resolve to a heading id produced by headings(), so the site's in-page links work like GitHub's.
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { findAnchor, ghSlug, headings, markdown } from './md.js';
import { search, sections, snippet, terms } from './search_engine.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

// GitHub slug rules, hand-checked against github.com anchors of these manuals.
assert.equal(ghSlug('1. Introduction: What is FLIKA?'), '1-introduction-what-is-flika');
assert.equal(ghSlug('25. The MMCore API: Key Methods'), '25-the-mmcore-api-key-methods');
assert.equal(ghSlug('Step 2 -- Load data'), 'step-2----load-data');
assert.equal(findAnchor(['22-temperature-co₂'], '22-temperature-co'), '22-temperature-co₂');
assert.equal(findAnchor(['a'], 'b'), null);
assert.deepEqual(headings('# T\n## A\n```\n## not\n```\n## A').map(h => h.id), ['t', 'a', 'a-1']);

// Renderer: escaping, fences with colours, nested lists, tables, links through linkFor.
const html = markdown('# Title\n\nSee <b>x</b> and [FLIKA](FLIKA_Manual.md).\n\n- a\n  - b\n\n| x | y |\n|---|---|\n| 1 | 2 |\n\n```python\nimport numpy as np  # c\n```',
  { skipTitle: true, linkFor: h => '#/manual/' + h });
assert.ok(!html.includes('<b>x</b>') && html.includes('&lt;b&gt;x&lt;/b&gt;'));
assert.ok(html.includes('href="#/manual/FLIKA_Manual.md"'));
assert.ok(/<ul><li>a<ul><li>b<\/li><\/ul><\/li><\/ul>/.test(html));
assert.ok(html.includes('<td>1</td>') && html.includes('<span class="tk-k">import</span>') && html.includes('tk-c'));
assert.ok(!html.includes('<h1') && !html.includes('Title'));

// Search: sections split at headings, all terms required, heading hits rank first.
const docs = [{ id: 'a', title: 'A', src: '# A\nintro\n## Mean squared displacement\nMSD of tracks\n## Other\nmsd once' },
  { id: 'b', title: 'B', src: '# B\n## Fitting\nnothing here' }];
assert.deepEqual(terms(' MSD  a tracks '), ['msd', 'tracks']);
assert.equal(sections(docs[0].src).length, 3);
const hits = search(docs, 'msd');
assert.deepEqual(hits.map(h => h.section), ['mean-squared-displacement', 'other']);
assert.equal(search(docs, 'msd fitting').length, 0);
assert.ok(snippet('x '.repeat(200) + 'needle here', ['needle']).startsWith('... '));

// Every in-page link in every manual resolves to one of its headings (GitHub-compatible anchors).
let checked = 0;
const broken = [];
for (const f of readdirSync(ROOT).filter(f => f.endsWith('_Manual.md'))) {
  const src = readFileSync(join(ROOT, f), 'utf8');
  const ids = headings(src).map(h => h.id);
  for (const m of src.matchAll(/\]\(#([^)\s]+)\)/g)) {
    checked++;
    if (findAnchor(ids, decodeURIComponent(m[1])) === null) broken.push(`${f}#${m[1]}`);
  }
}
assert.ok(checked > 500, `only ${checked} anchors found`);
assert.deepEqual(broken, [], `broken in-page links: ${broken.join(', ')}`);
console.log(`search_engine tests ok (${checked} manual anchors resolve)`);
